/**
 * EVALUADOR DE ACTIVOS (BRANCHING) — CommunityLab
 *
 * Entrada: resumen consolidado del lote.
 * Salida: decisiones de generación y evidencias clasificadas.
 *
 * Override explícito: opciones.generar_activos.
 * Sin override: se aplican las reglas automáticas.
 */

const input = $input.first()?.json ?? {};

const interacciones = Array.isArray(input.interacciones_analizadas)
  ? input.interacciones_analizadas
  : [];

const opciones = input.opciones ?? {};

const ACTIVOS_VALIDOS = [
  "LINKEDIN",
  "NEWSLETTER",
  "FAQ"
];

const testimoniosLogros = [];
const preguntasDudas = [];

// 1. Clasificar las interacciones por tipo de insight y sentimiento.
for (const item of interacciones) {
  const analisis = item.analisis ?? {};

  const tipoInsight = String(
    analisis.tipo_insight ?? ""
  ).trim().toLowerCase();

  const sentimiento = String(
    analisis.sentimiento ?? ""
  ).trim().toLowerCase();

  const esTestimonioOLogro =
    tipoInsight.includes("testimonio") ||
    tipoInsight.includes("logro");

  const esPositivo = sentimiento.includes("positi");

  const esPreguntaODuda =
    tipoInsight.includes("pregunta") ||
    tipoInsight.includes("duda") ||
    tipoInsight.includes("tecnica");

  if (esTestimonioOLogro && esPositivo) {
    testimoniosLogros.push(item);
  }

  if (esPreguntaODuda) {
    preguntasDudas.push(item);
  }
}

// 2. Determinar si hay un override explícito válido.
const overrideSolicitado =
  Array.isArray(opciones.generar_activos) &&
  opciones.generar_activos.length > 0;

let activosSolicitados;

if (overrideSolicitado) {
  activosSolicitados = [
    ...new Set(
      opciones.generar_activos
        .filter(valor => typeof valor === "string")
        .map(valor => valor.trim().toUpperCase())
        .filter(valor => ACTIVOS_VALIDOS.includes(valor))
    )
  ];
} else {
  activosSolicitados = [];

  if (testimoniosLogros.length > 0) {
    activosSolicitados.push("LINKEDIN", "NEWSLETTER");
  }

  if (preguntasDudas.length > 0) {
    activosSolicitados.push("FAQ");
  }
}

// 3. Construir una salida consistente para los siguientes nodos.
return [
  {
    json: {
      id_lote: input.id_lote ?? null,
      origen_comunidad: input.origen_comunidad ?? null,
      periodo_referencia: input.periodo_referencia ?? null,
      opciones,

      resumen_comunidad: input.resumen_comunidad ?? {},

      decisiones_branching: {
        generar_linkedin:
          activosSolicitados.includes("LINKEDIN"),

        generar_newsletter:
          activosSolicitados.includes("NEWSLETTER"),

        generar_faq:
          activosSolicitados.includes("FAQ"),

        activos_solicitados: activosSolicitados,
        modo_decision: overrideSolicitado
          ? "override"
          : "automatico"
      },

      evidencias: {
        testimonios_logros: testimoniosLogros,
        preguntas_dudas: preguntasDudas
      }
    }
  }
];

/**
 * Continuar cuando no hay activos a generar (o para forzar construcción).
 * Emite un item que permite al Merge/Construir cerrar el flujo.
 */
const input = $input.first().json;
const d = input.decisiones_branching || {};
const alguno = d.generar_linkedin || d.generar_newsletter || d.generar_faq;

if (alguno) {
  // Hay ramas activas: no emitir aquí (las cubren los generadores)
  return [];
}

// Ningún activo: emitir marcador para que Construir genere respuesta vacía de activos
return [{
  json: {
    status: "no_requerido",
    rama: "ninguno",
    ...input
  }
}];

/**
 * MOCK DE PRUEBA
 * Simula la salida del Analista LLM.
 * Mantiene los datos de entrada y devuelve el contrato esperado.
 */

const items = $input.all();

const temasEjemplo = [
  ["Logros y empleos", "Oracle Cloud (OCI)"],
  ["Dudas n8n", "LangGraph"],
  ["Despliegue OCI", "Always Free"],
  ["Dudas técnicas", "OCI Storage"],
  ["Feedback de cursos", "Prompt Engineering"],
  ["Experiencia de aprendizaje", "Comunidad"]
];

const tiposEjemplo = [
  "testimonio",
  "pregunta_tecnica",
  "logro",
  "duda",
  "feedback",
  "otro"
];

return items.map((item, index) => {
  const json = item.json;

  // El nodo anterior entrega "contenido".
  // "texto" se conserva como alternativa por compatibilidad.
  const contenido = String(
    json.contenido ?? json.texto ?? ""
  ).trim();

  const fragmento = contenido
    ? contenido.slice(0, 180)
    : "Contenido no disponible para la prueba.";

  const resumen = contenido
    ? `Análisis simulado de la interacción: ${contenido.slice(0, 120)}`
    : "No fue posible generar un resumen porque la actividad no contiene texto.";

  return {
    json: {
      ...json,

      status: "exito",

      analisis: {
        sentimiento: index % 3 === 0
          ? "Positivo"
          : index % 3 === 1
            ? "Neutro"
            : "Negativo",

        relevancia: ["Alta", "Media", "Baja"][index % 3],

        tipo_insight: tiposEjemplo[
          index % tiposEjemplo.length
        ],

        temas: temasEjemplo[
          index % temasEjemplo.length
        ],

        resumen,

        evidencia_clave: fragmento
      }
    }
  };
});

/**
 * ENSAMBLE PAQUETE DISTRIBUCIÓN — CommunityLab / LinkedIn Prompt V2
 * Acepta salida estructurada directa, wrapper {output: ...},
 * texto JSON en `text`, o arrays de wrappers como los mostrados en pruebas.
 */
const contextoBase = $('W4.2. Consolidar Análisis del Lote').first()?.json || {};
const itemsEntrada = $input.all();

function parseJsonString(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  try { return JSON.parse(trimmed); } catch (_) { return value; }
}

function unwrap(value, depth = 0) {
  if (depth > 6 || value == null) return value;
  let current = parseJsonString(value);
  if (Array.isArray(current)) {
    if (current.length === 1) return unwrap(current[0], depth + 1);
    return current.map(v => unwrap(v, depth + 1));
  }
  if (current && typeof current === 'object') {
    if (current.output !== undefined) return unwrap(current.output, depth + 1);
    if (current.result !== undefined && Object.keys(current).length <= 3) return unwrap(current.result, depth + 1);
    if (current.response !== undefined && Object.keys(current).length <= 3) return unwrap(current.response, depth + 1);
    if (current.text !== undefined && !current.titulo && !current.copy) {
      const parsedText = parseJsonString(current.text);
      if (parsedText !== current.text) return unwrap(parsedText, depth + 1);
    }
  }
  return current;
}

function isLinkedInAsset(value) {
  return value && typeof value === 'object' && (
    'titulo' in value || 'copy' in value || 'tipo_experiencia' in value || 'omitido' in value
  );
}

function normalizeLinkedIn(value) {
  if (!isLinkedInAsset(value)) return null;
  const asset = {
    titulo: typeof value.titulo === 'string' ? value.titulo : '',
    copy: typeof value.copy === 'string' ? value.copy : '',
    canal_recomendado: value.canal_recomendado || 'LinkedIn Oficial',
    potencial_engagement: ['Alto', 'Medio', 'Bajo'].includes(value.potencial_engagement) ? value.potencial_engagement : 'Bajo',
    hashtags: Array.isArray(value.hashtags) ? value.hashtags : [],
    origen_interacciones: Array.isArray(value.origen_interacciones) ? value.origen_interacciones : [],
    tipo_experiencia: value.tipo_experiencia || null
  };
  if (value.omitido === true) {
    asset.omitido = true;
    asset.motivo = typeof value.motivo === 'string' ? value.motivo : 'No hay material utilizable para redactar un post fiel.';
  }
  return asset;
}

let postLinkedin = { status: 'no_requerido' };
let sugerenciaFAQ = { status: 'no_requerido' };

for (const item of itemsEntrada) {
  const datosOriginales = item?.json ?? {};
  const datos = unwrap(datosOriginales);
  const candidatos = Array.isArray(datos) ? datos : [datos];
  for (const candidato of candidatos) {
    const linkedin = normalizeLinkedIn(candidato);
    if (linkedin) {
      postLinkedin = linkedin.omitido
        ? { ...linkedin, status: 'omitido' }
        : linkedin;
    } else if (candidato && typeof candidato === 'object' && (
      'tema' in candidato || 'contenido_sugerido' in candidato || 'origen' in candidato
    )) {
      sugerenciaFAQ = candidato;
    }
  }
}

const fechaISO = new Date().toISOString();
const timestamp = fechaISO.replace(/[:.-]/g, '');
const periodoRef = String(contextoBase.periodo_referencia || 'semana_actual').toLowerCase().replace(/\s+/g, '_');
const rutaObjetoOCI = `activos/${periodoRef}/paquete-${timestamp}.json`;
const activos = {};
// Se conserva el activo omitido en el paquete para dejar trazabilidad, pero se excluye de la curaduría/BD.
if (postLinkedin.status !== 'no_requerido' || postLinkedin.omitido === true) activos.post_linkedin = postLinkedin;
if (sugerenciaFAQ.status !== 'no_requerido') activos.sugerencia_contenido_faq = sugerenciaFAQ;

const paqueteFinal = {
  status: 'exito',
  id_lote: contextoBase.id_lote ?? null,
  origen_comunidad: contextoBase.origen_comunidad || 'Comunidad_General',
  periodo_referencia: contextoBase.periodo_referencia || 'Semana_Actual',
  resumen_comunidad: contextoBase.resumen_comunidad || {},
  activos_distribucion_generados: activos,
  meta: {
    procesado_en: fechaISO,
    modo: 'solo_oci',
    workflow_execution_id: $execution.id || 'ejecucion_local'
  }
};
return [{ json: paqueteFinal }];

/**
 * W4.2. CONSOLIDAR ANÁLISIS DEL LOTE
 * CommunityLab
 *
 * Entrada: actividades con análisis recuperadas desde PostgreSQL.
 * Salida: resumen agregado para Evaluador de Activos.
 *
 * Este nodo consolida resultados; no realiza un análisis LLM nuevo.
 */

const items = $input.all();

if (items.length === 0) {
  return [];
}

// Recuperar el contexto del lote creado al inicio.
const lote = $('Crear Lote de Procesamiento').first()?.json ?? {};

const origenComunidad = "Discord_Grupo_ONE_G10";
const periodoReferencia =
  lote.periodo_referencia ?? "periodo_no_definido";

// Conversión segura de temas, tanto si PostgreSQL devuelve
// un array como si devuelve una cadena JSON.
function normalizarTemas(valor) {
  if (Array.isArray(valor)) {
    return valor.filter(
      tema => typeof tema === "string" && tema.trim() !== ""
    );
  }

  if (typeof valor === "string") {
    try {
      const parsed = JSON.parse(valor);

      if (Array.isArray(parsed)) {
        return parsed.filter(
          tema => typeof tema === "string" && tema.trim() !== ""
        );
      }
    } catch (error) {
      // No interrumpir el lote por un campo de temas inválido.
    }
  }

  return [];
}

const interaccionesAnalizadas = [];
const conjuntoTemas = new Set();

const distribucion = {
  positivos: 0,
  neutros: 0,
  negativos: 0
};

for (const item of items) {
  const json = item.json;

  const sentimiento = String(
    json.sentimiento ?? "Neutro"
  ).trim();

  const relevancia = String(
    json.relevancia ?? "Media"
  ).trim();

  const tipoInsight = String(
    json.tipo_insight ?? "otro"
  ).trim();

  const temas = normalizarTemas(json.temas);

  const analisis = {
    sentimiento,
    relevancia,
    tipo_insight: tipoInsight,
    temas,
    resumen: json.resumen ?? "Sin resumen disponible.",
    evidencia_clave:
      json.evidencia_clave ?? json.contenido ?? ""
  };

  // Clasificar el sentimiento para el resumen agregado.
  const sentimientoNormalizado = sentimiento.toLowerCase();

  if (sentimientoNormalizado.includes("positi")) {
    distribucion.positivos++;
  } else if (sentimientoNormalizado.includes("nega")) {
    distribucion.negativos++;
  } else {
    distribucion.neutros++;
  }

  for (const tema of temas) {
    conjuntoTemas.add(tema);
  }

  interaccionesAnalizadas.push({
    id_actividad: json.id_actividad,
    id_lote: json.id_lote ?? lote.id_lote,

    // Conservar el tipo original declarado por la actividad.
    tipo_declarado: json.tipo_declarado ?? null,

    // Datos de contexto de la actividad.
    autor: json.autor ?? "Autor Desconocido",
    canal: json.canal ?? "Canal Desconocido",
    texto_original: json.contenido ?? "",

    // Resultado del analista.
    analisis
  });
}

// Determinar el sentimiento predominante.
// En caso de empate, se utiliza Neutro como resultado conservador.
const conteos = [
  ["Positivo", distribucion.positivos],
  ["Neutro", distribucion.neutros],
  ["Negativo", distribucion.negativos]
];

const maximo = Math.max(...conteos.map(([, cantidad]) => cantidad));
const ganadores = conteos.filter(
  ([, cantidad]) => cantidad === maximo
);

const sentimientoPredominante =
  ganadores.length === 1 ? ganadores[0][0] : "Neutro";

return [
  {
    json: {
      id_lote: lote.id_lote ?? items[0].json.id_lote,
      origen_comunidad: origenComunidad,
      periodo_referencia: periodoReferencia,

      // Override temporal de pruebas: permite comprobar
      // las tres ramas de generación de activos.
      opciones: {
        generar_activos: [
          "LINKEDIN",
          "NEWSLETTER",
          "FAQ"
        ]
      },

      resumen_comunidad: {
        total_interacciones_procesadas:
          interaccionesAnalizadas.length,
        sentimiento_predominante: sentimientoPredominante,
        distribucion_sentimientos: distribucion,
        temas_principales: Array.from(conjuntoTemas)
      },

      interacciones_analizadas: interaccionesAnalizadas
    }
  }
];

const resultados = $input.all();
const actividades = $('Asignar Lote a Actividades Pendientes').all();

if (resultados.length !== actividades.length) {
  throw new Error(
    `Cantidad diferente de elementos: ${resultados.length} análisis y ${actividades.length} actividades originales.`
  );
}

return resultados.map((item, index) => {
  const actividad = actividades[index].json;
  const a = item.json.output;

  if (!a) {
    throw new Error(
      `No se encontró output en el análisis del elemento ${index + 1}.`
    );
  }

  const score = Number(a.score_relevancia);

  if (!Number.isInteger(score) || score < 1 || score > 10) {
    throw new Error(
      `score_relevancia inválido para actividad ${actividad.id_actividad}.`
    );
  }

  const relevancia =
    score <= 3 ? 'Baja' :
    score <= 6 ? 'Media' :
    'Alta';

  return {
  json: {
    id_actividad: Number(actividad.id_actividad),
    analisis: {
      sentimiento: a.sentimiento,
      relevancia,
      tipo_insight: a.tipo_insight,
      temas: a.tema_libre ? [a.tema_libre] : [],
      resumen: a.resumen,
      evidencia_clave: a.cita_extraida,
      resultado_json: a
    }
  }
};
});

// Script rápido para el output final si se añade un nodo Code tras OCI
const entrada = $input.first().json;

entrada.decisiones_branching.generar_linkedin = true;
entrada.decisiones_branching.generar_newsletter = true;
entrada.decisiones_branching.generar_faq = true;

return [{ json: entrada }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "sentimiento": {
      "type": "string",
      "enum": [
        "Muy Positivo",
        "Positivo",
        "Neutral",
        "Frustración",
        "Negativo"
      ]
    },
    "tema_categoria": {
      "type": "string",
      "enum": [
        "Logro Laboral",
        "Duda Técnica",
        "Feedback de Curso",
        "Testimonio de Proyecto",
        "Otro"
      ]
    },
    "tema_libre": {
      "type": "string"
    },
    "score_relevancia": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10
    },
    "tipo_insight": {
      "type": "string",
      "enum": [
        "testimonio",
        "duda_recurrente",
        "logro",
        "feedback",
        "ninguno"
      ]
    },
    "resumen": {
      "type": "string"
    },
    "cita_extraida": {
      "type": "string"
    },
    "razon_relevancia": {
      "type": "string"
    }
  },
  "required": [
    "sentimiento",
    "tema_categoria",
    "tema_libre",
    "score_relevancia",
    "tipo_insight",
    "resumen",
    "cita_extraida",
    "razon_relevancia"
  ],
  "additionalProperties": false
}
